#include <stdlib.h>
#include <string.h>
#include <omp.h>

#if defined(__AVX512F__)
#define VW 16
#define MR 12
#define ROWS(X) X(0) X(1) X(2) X(3) X(4) X(5) X(6) X(7) X(8) X(9) X(10) X(11)
#else
#define VW 8
#define MR 6
#define ROWS(X) X(0) X(1) X(2) X(3) X(4) X(5)
#endif
#define NR (2 * VW)
#define KC 256
#define MC (MR * 8)
#define NC (NR * 6)

typedef float vf __attribute__((vector_size(VW * 4)));

static inline vf ldu(const float *p) { vf v; memcpy(&v, p, sizeof(v)); return v; }
static inline void stu(float *p, vf v) { memcpy(p, &v, sizeof(v)); }

static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int mr, int nr, int accum)
{
#define DECL(i) vf c##i##_0 = {0}, c##i##_1 = {0};
    ROWS(DECL)
#undef DECL

#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)(b);
        vf b1 = *(const vf *)(b + VW);
        __builtin_prefetch(b + 8 * NR);
#define FMA(i) { vf av = (vf){0} + a[i]; c##i##_0 += av * b0; c##i##_1 += av * b1; }
        ROWS(FMA)
#undef FMA
        a += MR;
        b += NR;
    }

    if (mr == MR && nr == NR) {
        if (accum) {
#define STA(i) { float *r = c + (size_t)(i) * ldc; \
                 stu(r, ldu(r) + c##i##_0); stu(r + VW, ldu(r + VW) + c##i##_1); }
            ROWS(STA)
#undef STA
        } else {
#define STS(i) { float *r = c + (size_t)(i) * ldc; stu(r, c##i##_0); stu(r + VW, c##i##_1); }
            ROWS(STS)
#undef STS
        }
    } else {
        float tmp[MR * NR] __attribute__((aligned(64)));
#define STT(i) { stu(tmp + (i) * NR, c##i##_0); stu(tmp + (i) * NR + VW, c##i##_1); }
        ROWS(STT)
#undef STT
        if (accum) {
            for (int i = 0; i < mr; i++)
                for (int j = 0; j < nr; j++)
                    c[(size_t)i * ldc + j] += tmp[i * NR + j];
        } else {
            for (int i = 0; i < mr; i++)
                for (int j = 0; j < nr; j++)
                    c[(size_t)i * ldc + j] = tmp[i * NR + j];
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int mp = (n + MR - 1) / MR;
    int np = (n + NR - 1) / NR;

    size_t abytes = ((size_t)mp * MR * n * sizeof(float) + 63) & ~(size_t)63;
    size_t bbytes = ((size_t)np * NR * n * sizeof(float) + 63) & ~(size_t)63;
    float *Ap = (float *)aligned_alloc(64, abytes);
    float *Bp = (float *)aligned_alloc(64, bbytes);

    int ntm = (n + MC - 1) / MC;
    int ntn = (n + NC - 1) / NC;

    #pragma omp parallel proc_bind(close)
    {
        /* pack A: panel r holds rows r*MR..r*MR+MR-1, layout [k][MR] over all k */
        #pragma omp for schedule(static) nowait
        for (int r = 0; r < mp; r++) {
            float *dst = Ap + (size_t)r * n * MR;
            for (int i = 0; i < MR; i++) {
                int row = r * MR + i;
                if (row < n) {
                    const float *src = A + (size_t)row * n;
                    for (int k = 0; k < n; k++) dst[(size_t)k * MR + i] = src[k];
                } else {
                    for (int k = 0; k < n; k++) dst[(size_t)k * MR + i] = 0.0f;
                }
            }
        }

        /* pack B: panel p holds cols p*NR..p*NR+NR-1, layout [k][NR] over all k */
        #pragma omp for schedule(static)
        for (int p = 0; p < np; p++) {
            int j0 = p * NR;
            int nr = n - j0 < NR ? n - j0 : NR;
            float *dst = Bp + (size_t)p * n * NR;
            const float *src = B + j0;
            if (nr == NR) {
                for (int k = 0; k < n; k++)
                    memcpy(dst + (size_t)k * NR, src + (size_t)k * n, NR * sizeof(float));
            } else {
                for (int k = 0; k < n; k++) {
                    int j = 0;
                    for (; j < nr; j++) dst[(size_t)k * NR + j] = src[(size_t)k * n + j];
                    for (; j < NR; j++) dst[(size_t)k * NR + j] = 0.0f;
                }
            }
        }

        #pragma omp for schedule(dynamic, 1) collapse(2)
        for (int ti = 0; ti < ntm; ti++) {
            for (int tj = 0; tj < ntn; tj++) {
                int ic = ti * MC, jc = tj * NC;
                int mc = n - ic < MC ? n - ic : MC;
                int nc = n - jc < NC ? n - jc : NC;
                for (int pc = 0; pc < n; pc += KC) {
                    int kc = n - pc < KC ? n - pc : KC;
                    int accum = pc > 0;
                    for (int jr = 0; jr < nc; jr += NR) {
                        int nr = nc - jr < NR ? nc - jr : NR;
                        const float *bp = Bp + (size_t)((jc + jr) / NR) * n * NR + (size_t)pc * NR;
                        for (int ir = 0; ir < mc; ir += MR) {
                            int mr = mc - ir < MR ? mc - ir : MR;
                            const float *ap = Ap + (size_t)((ic + ir) / MR) * n * MR + (size_t)pc * MR;
                            kernel(kc, ap, bp, C + (size_t)(ic + ir) * n + jc + jr,
                                   n, mr, nr, accum);
                        }
                    }
                }
            }
        }
    }
    free(Ap);
    free(Bp);
}
